import { Stage } from "../Stage"

export default class extends Stage {
    protected *G(): Generator<void, void, unknown> {
        yield* this.wait(30)

        yield* this.text(`「新聞屋さん、暇なら茶化しに来た?」`, { name: "シオン" })
        yield* this.text(`「いや。」`, { name: "マス" })
        yield* this.text(`珍しく、マスは煙草に火を点けなかった。`)

        yield* this.text(`「アオに、最後に取材した時のこと、話してなかったよな。」`, { name: "マス" })
        yield* this.text(`「聞きたくない。」`, { name: "シオン" })
        yield* this.text(`「勝手に話す。」`, { name: "マス" })

        yield* this.text(`「"僕らはきっと、分かり合えない"って言ってた。」`, { name: "マス" })
        yield* this.text(`「あの人が? 冗談でしょ。」`, { name: "シオン" })
        yield* this.text(`「本気だったよ。でも、それで終わりじゃなかった。」`, { name: "マス" })

        yield* this.text(`「分かり合えなくても、隣にいることはできる。傷つけられたことを、許すこともできる。それだけなら、と言ってた。」`, { name: "マス" })

        yield* this.text(`「……綺麗事。」`, { name: "シオン" })
        yield* this.text(`「かもな。だが、あいつはそれを信じて、あの女に手を伸ばしたまま死んだ。」`, { name: "マス" })

        yield* this.text(`少女は何も言えなかった。`)
        yield* this.text(`「あたしは、分かり合えると思ってた。」`, { name: "シオン" })
        yield* this.text(`「うん。」`, { name: "マス" })
        yield* this.text(`「でも、無理なんだ、多分。」`, { name: "シオン" })
        yield* this.text(`「……それでも?」`, { name: "マス" })

        yield* this.text(`少女はしばらく黙ってから、`)
        yield* this.text(`「……許すことくらいは、できるかもね。」`, { name: "シオン" })

        yield* this.text(`マスは何も言わず、煙草を仕舞った。`)
    }
}
